const fn = new Function(code + "\nreturn { resolveConflict, chooseRecovery, bumpVersion };");
const { resolveConflict } = fn();
if (resolveConflict("a", "b", "mine") !== "a") throw new Error("'mine' keeps our side.");
if (resolveConflict("a", "b", "theirs") !== "b") throw new Error("'theirs' takes the incoming side.");
if (resolveConflict("a", "b", "combine") !== "a\nb") throw new Error("'combine' stacks both sides with a newline.");

const fn = new Function(code + "\nreturn { resolveConflict, chooseRecovery, bumpVersion };");
const { chooseRecovery } = fn();
if (chooseRecovery(true, true, true) !== "revert") throw new Error("Pushed + pulled => only revert is safe.");
if (chooseRecovery(false, false, true) !== "reset") throw new Error("Never pushed => reset is fine.");
if (chooseRecovery(true, false, true) !== "merge") throw new Error("Pushed, not pulled, history wanted => merge.");
if (chooseRecovery(true, false, false) !== "reset") throw new Error("Pushed, not pulled, history disposable => reset.");

const fn = new Function(code + "\nreturn { resolveConflict, chooseRecovery, bumpVersion };");
const { bumpVersion } = fn();
if (bumpVersion("1.2.3", "fix") !== "1.2.4") throw new Error("fix bumps patch.");
if (bumpVersion("1.2.3", "feat") !== "1.3.0") throw new Error("feat bumps minor and zeroes patch.");
if (bumpVersion("1.2.3", "feat!") !== "2.0.0") throw new Error("Breaking changes bump major and zero minor+patch.");
if (bumpVersion("2.0.5", "BREAKING CHANGE") !== "3.0.0") throw new Error("The BREAKING CHANGE footer behaves like '!'.");
